import { DatabaseSync } from 'node:sqlite'
import path from 'node:path'
import fs from 'node:fs'

let _db: DatabaseSync | null = null

// Server utility: opens the SQLite database generated by make setup
export function getDb(): DatabaseSync {
  if (!_db) {
    // Look for app.sqlite in .data directory
    let dbPath = path.resolve(process.cwd(), '.data/app.sqlite')
    if (!fs.existsSync(dbPath)) {
      dbPath = path.resolve(process.cwd(), 'run-06/.data/app.sqlite')
    }
    _db = new DatabaseSync(dbPath)
  }
  return _db
}
